}

export const BookGrid: React.FC<BookGridProps> = ({ onBookSelect }) => {
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => setIsVisible(true), 200);
    return () => clearTimeout(timer);
  }, []);

  return (
    <div className="grid grid-cols-1 md:grid-cols-3 gap-10 lg:gap-14 max-w-7xl mx-auto px-4">
      {BOOKS.map((book, idx) => (
        <div 
          key={book.id} 
          onClick={() => onBookSelect(book)}
          className={`cursor-pointer group flex flex-col transition-all duration-1000 transform ${
            isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-12'
          }`}
          style={{ transitionDelay: `${idx * 150}ms` }}
        >
          <div className="relative h-full flex flex-col p-6 rounded-sm border border-white/5 bg-white/[0.02] backdrop-blur-sm shadow-xl transition-all duration-500 hover:bg-white/[0.05] hover:border-red-900/40 hover:shadow-[0_0_40px_rgba(153,27,27,0.1)]">

            {/* Glossy Overlay */}
            <div className="absolute inset-0 bg-gradient-to-tr from-transparent via-white/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-700 pointer-events-none" />

            {/* Cover Area */}
            <div className="relative w-full aspect-[2/3] mb-8 overflow-hidden rounded-sm shadow-2xl ring-1 ring-white/10">
              <BookCover book={book} className="w-full h-full" />
            </div>

            {/* Details */}
            <div className="text-center">
              <span className="text-red-500 text-[10px] font-bold uppercase tracking-[0.3em] mb-4 block group-hover:text-red-400 transition-colors">
                {book.subtitle}
              </span>
              <h3 className="text-2xl font-cinzel text-white mb-4 group-hover:text-yellow-400 transition-colors duration-500 leading-snug">
                {book.title}
              </h3>
              <div className="w-8 h-[1px] bg-white/10 mx-auto mb-6 group-hover:w-16 transition-all duration-500" />
              <p className="text-sm text-gray-400 leading-relaxed font-normal line-clamp-3 group-hover:text-gray-200 transition-colors">
                {book.description}
              </p>
            </div>
          </div>
        </div>
