interface BookGridProps {
  onBookSelect: (book: Book) => void;
}

export const BookGrid: React.FC<BookGridProps> = ({ onBookSelect }) => {
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => setIsVisible(true), 100);
    return () => clearTimeout(timer);
  }, []);

  return (
    <div className="grid grid-cols-1 md:grid-cols-3 gap-12 lg:gap-16 max-w-7xl mx-auto px-6">
      {BOOKS.map((book, idx) => (
        <div 
          key={book.id} 
          onClick={() => onBookSelect(book)}
          className={`cursor-pointer group transition-all duration-1000 transform ${
            isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-8'
          }`}
          style={{ transitionDelay: `${idx * 150}ms` }}
        >
          {/* Card Container */}
          <div className="relative flex flex-col bg-white/[0.01] border border-white/5 p-4 md:p-6 transition-all duration-500 hover:border-red-900/30 hover:bg-white/[0.03] shadow-2xl">

            {/* 2D Cover Image Container */}
            <div className="relative aspect-[2/3] w-full mb-8 overflow-hidden rounded-sm ring-1 ring-white/10 group-hover:ring-red-900/40 transition-all duration-500">
               <BookCover book={book} />
            </div>

            {/* Typography - Matches the Image Artwork hierarchy */}
            <div className="text-center px-4">
              <span className="text-red-600 text-[10px] font-bold uppercase tracking-[0.4em] mb-3 block group-hover:text-red-400 transition-colors">
                {book.subtitle}
              </span>
              <h3 className="text-xl md:text-2xl font-cinzel text-white mb-4 group-hover:text-yellow-500 transition-colors duration-500 tracking-wider">
                {book.title}
              </h3>
              <div className="w-6 h-[1px] bg-white/10 mx-auto mb-6 group-hover:w-12 transition-all duration-500" />
              <p className="text-xs md:text-sm text-gray-400 leading-relaxed font-normal font-montserrat line-clamp-3 group-hover:text-gray-200">
                {book.description}
              </p>
            </div>
          </div>
        </div>
      ))}
    </div>
  );
};

